content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --bg-color: #f3f4f6;
  --card-bg: #ffffff;
  --text-main: #1f2937;
  --text-muted: #6b7280;
  --border-color: #d1d5db;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --history-bg: #f9fafb;
}

@media (prefers-color-scheme: dark) {
  :root {
    --primary-color: #6366f1;
    --primary-hover: #4f46e5;
    --bg-color: #111827;
    --card-bg: #1f2937;
    --text-main: #f9fafb;
    --text-muted: #9ca3af;
    --border-color: #374151;
    --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.3), 0 2px 4px -1px rgba(0, 0, 0, 0.18);
    --history-bg: #1f2937;
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  padding: 20px;
  transition: background-color 0.3s, color 0.3s;
}

.app-container {
  max-width: 600px;
  margin: 0 auto;
  padding: 10px;
}

.header {
  text-align: center;
  margin-bottom: 24px;
}

.header h1 {
  font-size: 1.8rem;
  color: var(--primary-color);
  margin-bottom: 4px;
}

.header p {
  color: var(--text-muted);
  font-size: 0.95rem;
}

.card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px;
  margin-bottom: 20px;
  transition: transform 0.2s ease, box-shadow 0.2s ease, background-color 0.3s;
}

.card:hover {
  box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
}

.form-group {
  margin-bottom: 16px;
}

.label {
  display: block;
  font-weight: 600;
  margin-bottom: 6px;
  font-size: 0.9rem;
}

.input {
  width: 100%;
  padding: 10px 14px;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  font-size: 1rem;
  background-color: var(--card-bg);
  color: var(--text-main);
  transition: border-color 0.2s, box-shadow 0.2s, background-color 0.3s;
}

.input:focus {
  outline: none;
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.15);
}

.btn {
  display: inline-block;
  width: 100%;
  padding: 12px;
  background-color: var(--primary-color);
  color: white;
  border: none;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s, box-shadow 0.2s;
  text-align: center;
}

.btn:hover {
  background-color: var(--primary-hover);
  box-shadow: 0 4px 12px rgba(79, 70, 229, 0.3);
}

.btn:active {
  transform: scale(0.98);
}

.result-section {
  text-align: center;
  margin-top: 20px;
  padding-top: 20px;
  border-top: 1px solid var(--border-color);
}

.bmi-value {
  font-size: 2.5rem;
  font-weight: bold;
  color: var(--primary-color);
  margin: 8px 0;
}

.bmi-status {
  font-size: 1.2rem;
  font-weight: 600;
  padding: 4px 12px;
  border-radius: 20px;
  display: inline-block;
  margin-top: 4px;
}

.history-section {
  margin-top: 24px;
}

.history-section h2 {
  font-size: 1.2rem;
  margin-bottom: 12px;
  color: var(--text-main);
}

.history-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  background-color: var(--history-bg);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  margin-bottom: 8px;
  font-size: 0.9rem;
  transition: background-color 0.2s, transform 0.1s;
}

.history-item:hover {
  filter: brightness(0.97);
}

.history-item span {
  color: var(--text-muted);
}

@media (max-width: 480px) {
  body {
    padding: 10px;
  }

  .app-container {
    padding: 0;
  }

  .card {
    padding: 16px;
  }

  .header h1 {
    font-size: 1.5rem;
  }

  .bmi-value {
    font-size: 2rem;
  }

  .history-item {
    flex-direction: column;
    align-items: flex-start;
    gap: 4px;
  }
}

import { useState, useEffect } from 'react';

interface HistoryItem {
  id: string;
  height: number;
  weight: number;
  bmi: number;
  status: string;
  date: string;
}

export default function App() {
  const [height, setHeight] = useState<string>('');
  const [weight, setWeight] = useState<string>('');
  const [currentBmi, setCurrentBmi] = useState<number | null>(null);
  const [currentStatus, setCurrentStatus] = useState<string>('');
  const [history, setHistory] = useState<HistoryItem[]>(() => {
    const saved = localStorage.getItem('bmi_history');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('bmi_history', JSON.stringify(history));
  }, [history]);

  const calculateBmi = (e: React.FormEvent) => {
    e.preventDefault();
    const h = parseFloat(height);
    const w = parseFloat(weight);

    if (!h || !w || h <= 0 || w <= 0 || h > 250 || w > 300) {
      alert('正しい身長（1〜250cm）と体重（1〜300kg）を入力してください。');
      return;
    }

    const heightInMeters = h / 100;
    const bmi = w / (heightInMeters * heightInMeters);
    const roundedBmi = Math.round(bmi * 10) / 10;
    const status = getBmiStatus(roundedBmi);

    setCurrentBmi(roundedBmi);
    setCurrentStatus(status);

    const newItem: HistoryItem = {
      id: Date.now().toString(),
      height: h,
      weight: w,
      bmi: roundedBmi,
      status,
      date: new Date().toLocaleDateString('ja-JP', {
        month: 'numeric',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
      }),
    };

    setHistory([newItem, ...history]);
    setHeight('');
    setWeight('');
  };

  const clearHistory = () => {
    setHistory([]);
    localStorage.removeItem('bmi_history');
  };

  const getBmiStatus = (bmi: number): string => {
    if (bmi < 18.5) return '低体重（やせ）';
    if (bmi < 25) return '普通体重';
    if (bmi < 30) return '肥満（1度）';
    if (bmi < 35) return '肥満（2度）';
    if (bmi < 40) return '肥満（3度）';
    return '肥満（4度）';
  };

  const getStatusColor = (status: string) => {
    if (status.includes('やせ')) return '#3b82f6';
    if (status.includes('普通')) return '#10b981';
    if (status.includes('1度')) return '#f59e0b';
    return '#ef4444';
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1>BMI & 肥満度チェッカー</h1>
        <p>身長と体重を入力して、あなたのBMIと肥満度をチェックしましょう</p>
      </header>

      <div className="card">
        <form onSubmit={calculateBmi}>
          <div className="form-group">
            <label className="label" htmlFor="height">身長 (cm)</label>
            <input
              id="height"
              className="input"
              type="number"
              step="0.1"
              placeholder="例: 170"
              value={height}
              onChange={(e) => setHeight(e.target.value)}
            />
          </div>

          <div className="form-group">
            <label className="label" htmlFor="weight">体重 (kg)</label>
            <input
              id="weight"
              className="input"
              type="number"
              step="0.1"
              placeholder="例: 65"
              value={weight}
              onChange={(e) => setWeight(e.target.value)}
            />
          </div>

          <button type="submit" className="btn">計算する</button>
        </form>

        {currentBmi !== null && (
          <div className="result-section">
            <p className="label">あなたのBMI</p>
            <div className="bmi-value">{currentBmi}</div>
            <div
              className="bmi-status"
              style={{
                backgroundColor: `${getStatusColor(currentStatus)}20`,
                color: getStatusColor(currentStatus),
              }}
            >
              {currentStatus}
            </div>
          </div>
        )}
      </div>

      {history.length > 0 && (
        <div className="card history-section">
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
            <h2 style={{ margin: 0 }}>計算履歴</h2>
            <button
              onClick={clearHistory}
              style={{
                background: 'transparent',
                border: '1px solid var(--border-color)',
                borderRadius: '6px',
                padding: '4px 8px',
                fontSize: '0.8rem',
                color: 'var(--text-muted)',
                cursor: 'pointer'
              }}
            >
              履歴をすべて削除
            </button>
          </div>
          {history.map((item) => (
            <div key={item.id} className="history-item">
              <div>
                <strong>BMI: {item.bmi}</strong> ({item.status})
                <br />
                <span>身長: {item.height}cm / 体重: {item.weight}kg</span>
              </div>
              <span>{item.date}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
